def transform(grid):
    # Mark background gaps between aligned 7s, extending only through nearby aligned segments.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    fg = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    # For every row, fill bg gaps between consecutive foregrounds when gap <= 3 cells.
    for r in range(h):
        pts=[c for c in range(w) if grid[r][c]==fg]
        for a,b in zip(pts,pts[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    # Fill same-column gaps between consecutive fg cells when distance <= 4.
    for c in range(w):
        pts=[r for r in range(h) if grid[r][c]==fg]
        for a,b in zip(pts,pts[1:]):
            if b-a <= 4:
                for r in range(a+1,b):
                    if grid[r][c]==bg: out[r][c]=2
    return out
