def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg=next(v for row in grid for v in row if v!=bg)
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(1,w-1):
            if grid[r][c]==bg and grid[r][c-1]==fg and grid[r][c+1]==fg:
                out[r][c]=2
    for c in range(w):
        for r in range(1,h-1):
            if grid[r][c]==bg and grid[r-1][c]==fg and grid[r+1][c]==fg:
                out[r][c]=2
    return out
